  [8, line("~ 2 ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ 6 ~ ~ ~", "~ ~ ~ ~ 5 ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ ~", "~ ~ 4 ~ ~ ~ ~ ~ ~ 6 ~ ~ ~ ~ 5 ~", "~ ~ ~ ~ ~ ~ 3 ~ ~ ~ ~ ~ 2 ~ ~ ~")],
  [8, line("~ ~ ~ 4 ~ ~ ~ ~ ~ ~ ~ ~ ~ 2 ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ 4 ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~", "~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~ ~")]
